// Verificacion del código de estado 200
pm.test("Verificar que la respuesta sea 200", function () {
    pm.response.to.have.status(200);
});

// Verificacion que el tiempo de respuesta sea menor a 5000 ms
pm.test("Verificar que el tiempo de respuesta sea menor a 1000 ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(9000);
});

// Verificacion que el body no esté vacío
pm.test("Verificar que el body no este vacio", function () {
    pm.response.to.be.withBody;
    pm.response.to.be.json;
});

// Verificacion Content-Type
pm.test("Verificar Content-Type sea application/json", function () {
    pm.response.to.have.header("Content-Type");
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

// Verificacion tamaño de respuesta
pm.test("Verificar que la respuesta tenga un tamano mayor a 0", function () {
    pm.expect(pm.response.responseSize).to.be.above(0);
});
